    num[2] = num[2] - 100 * num[3]; // lakhs

    for (int i = 3; i > 0; i--)
    {
        if (num[i] != 0)
        {
            first = i;
            break;
        }
    }
    for (int i = first; i >= 0; i--)
    {
        if (num[i] == 0) continue;
        u = num[i] % 10; // ones
        t = num[i] / 10;
        h = num[i] / 100; // hundreds
        t = t - 10 * h; // tens
